const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(value,precise=false)=>value===null||value===undefined?'Needs price':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:precise||!Number.isInteger(Number(value))?2:0,maximumFractionDigits:precise?2:(Number.isInteger(Number(value))?0:2)}).format(Number(value));
const initials=name=>String(name).split(' ').map(x=>x[0]).slice(0,2).join('');
const duration=minutes=>minutes===null?'Needs estimate':minutes>=60?`${Math.floor(minutes/60)}h ${minutes%60}m`:`${minutes} min`;
const dateText=date=>new Intl.DateTimeFormat('en-US',{weekday:'long',month:'long',day:'numeric',timeZone:'UTC'}).format(new Date(date+'T12:00:00Z'));
const pageInfo={week:['Weekly plan','ROOM FOR THE WHOLE WEEK','A week with room to breathe.','Balance daily job limits, crew capacity and labor costs before dispatch.'],today:['Today’s plan','LET’S MAKE TODAY A GOOD ONE','Your day, well planned.','A clear route. A confident quote. A crew that’s ready to go.'],jobs:['Customers & jobs','THE PEOPLE BEHIND THE PLAN','Good work starts with good details.','Your customer list, requested services, and the details that keep a visit on track.'],pricing:['Price studio','KNOW THE WORK. KNOW YOUR WORTH.','A confident quote starts here.','Build a price from your costs, then compare it with past work and sourced examples.'],crew:['Crew view','OUT IN THE FIELD','The next stop, made simple.','Your mobile crew preview. Start work, report progress, and record a job well done.'],review:['Day review','BRING IT ALL TOGETHER','Good work deserves a clear finish.','Review the completed visits, their costs, and the customer messages ready to go.']};
let data,seed,baseline,plan,importPreview=null,toastTimer,activeDrafts=[],importWorkbook=null,excelRows=null,excelWarnings=[];
let state={optimized:false,crew:'A',selected:null,quoteJob:'J02',search:'',filter:'all',zoom:1,connections:false};
let destroyStreetMap=()=>{};
const roadLoad={busy:false,error:'',failedKey:null,message:''};
const content=document.getElementById('page-content');
const ops=createOperationsUI({getData:()=>data,setData:next=>data=next,getState:()=>state,getPlan:()=>plan,esc,money,clockLabel,dateText,toast,save,render,go,serviceTags});
const landscape=createLandscapeUI({getData:()=>data,getState:()=>state,getPlan:()=>plan,selectedDate:()=>ops.selectedDate(),esc,money,icon,save,render,go,toast,mapPanel,weatherPanel,openJob,download});
const bulkPricing=createBulkPricingUI({getData:()=>data,getState:()=>state,esc,money,icon,save,render,toast,go});
const defaultBusinessState=structuredClone(state);
const business=createBusinessAccess({getData:()=>data,getState:()=>state,esc,icon,toast,download,onLock:()=>{destroyStreetMap();data=null;baseline=null;plan=null;state=structuredClone(defaultBusinessState);importPreview=null;importWorkbook=null;excelRows=null;activeDrafts=[];content.innerHTML='';document.querySelectorAll('dialog').forEach(dialog=>{if(dialog.open)dialog.close();dialog.replaceChildren();dialog.remove();});document.querySelector('.workspace-shell')?.remove();}});
Object.assign(pageInfo,{today:['Today','OPERATIONS OVERVIEW','Today’s work','Your schedule, your crews, and what needs attention.'],week:['Crew schedule','PLAN THE WORK','Crew schedule','A shared view of assignments, capacity and unscheduled work.'],projects:['Projects','PROJECT WORKSPACE','Projects','Manage ongoing care and installation work with clear costs and next steps.'],project:['Projects','PROJECT DETAILS','Project details',''],planning:['Week optimizer','WEEKLY CAPACITY','Balance the workweek','Compare a proposed schedule before applying changes.'],crew:['Crews','CREW CHECK-IN','Crew assignments','The day’s visits, addresses and reported progress.']});
function dayData(){return workspaceForDay(data,state.viewDate||data.date);}
function page(){const hash=location.hash.slice(1);return hash.startsWith('project/')?'project':Object.hasOwn(pageInfo,hash)?hash:'today';}
function save(){if(data)business.queueSave();}
function toast(message){clearTimeout(toastTimer);const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');toastTimer=setTimeout(()=>el.classList.remove('visible'),4500);}
function getJob(id){return data.jobs.find(j=>j.id===id);}
function getCrew(id){return data.crews.find(c=>c.id===id);}
function routingWorkKey(){
 const current=planLawnDay(dayData(),state.optimized);
 return roadFingerprint(data)+'|'+current.routes.map(route=>route.crewId+':'+route.stops.map(stop=>stop.id).join(',')).join('|');
}
function roadGeometryReady(route){const spec=roadRouteSpec(data,route);return !spec||data.roadShapes?.[route.crewId]?.key===spec.key;}
function routingRepaint(){
 baseline=planLawnDay(dayData(),false);plan=state.optimized?planLawnDay(dayData(),true):baseline;
 // Preserve any price inputs the owner is still editing.
 if(page()!=='pricing')render();
}
async function ensureRoadRouting(force=false){
 if(!data?.geographic||roadLoad.busy)return;
 const workKey=routingWorkKey();
 if(!force&&roadLoad.failedKey===workKey)return;
 const matching=roadMatrixMatches(data),age=Date.now()-Date.parse(data.roadMatrix?.fetchedAt||'');
 const refreshMatrix=force||!matching||!Number.isFinite(age)||age>24*60*60*1000;
 const current=planLawnDay(dayData(),state.optimized);
 if(!refreshMatrix&&current.routes.every(roadGeometryReady))return;
 const workspace=data,fingerprint=roadFingerprint(data);
 Object.assign(roadLoad,{busy:true,error:'',failedKey:null,message:refreshMatrix?'Loading road driving times…':'Drawing routes along the roads…'});
 routingRepaint();
 try{
  if(refreshMatrix){
   const points=roadPoints(data),matrix=await loadRoadMatrix(points,{refresh:force,onProgress:(done,total)=>{if(total>1){roadLoad.message='Loading road driving times · batch '+done+' of '+total+'…';routingRepaint();}}});
   if(data!==workspace||roadFingerprint(data)!==fingerprint)return;
   data.roadMatrix=matrix;data.roadShapes={};save();
   roadLoad.message='Drawing routes along the roads…';routingRepaint();
  }
  const selected=planLawnDay(dayData(),state.optimized),errors=[];
  for(const route of selected.routes){
   const spec=roadRouteSpec(data,route);if(!spec||data.roadShapes?.[route.crewId]?.key===spec.key)continue;
   try{
    const shape=await loadRoadRoute(spec,{refresh:force});
    if(data!==workspace||roadFingerprint(data)!==fingerprint)return;
    const latest=planLawnDay(dayData(),state.optimized).routes.find(candidate=>candidate.crewId===route.crewId);
    if(roadRouteSpec(data,latest)?.key!==spec.key)continue;
    const timed=[...latest.stops.map(stop=>stop.travelMinutes),latest.stops.at(-1).returnMinutes];
    if(shape.legs.some((leg,index)=>Math.abs(Math.ceil(leg.seconds/60)-timed[index])>1))throw Error('The displayed route and driving-time table disagree. Refresh road routes.');
    data.roadShapes??={};data.roadShapes[route.crewId]=shape;save();routingRepaint();
   }catch(error){errors.push((getCrew(route.crewId)?.name||route.crewId)+': '+error.message);}
  }
  if(errors.length)throw Error(errors.join(' '));
 }catch(error){roadLoad.error=error.message;roadLoad.failedKey=routingWorkKey();}
 finally{
  roadLoad.busy=false;routingRepaint();
  if(routingWorkKey()!==workKey&&!roadLoad.error)queueMicrotask(()=>ensureRoadRouting());
 }
}
function roadStatus(){
 const ready=roadMatrixMatches(data),pending=plan.routes.some(route=>!roadGeometryReady(route));
 const queried=ready?new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZone:'America/New_York',timeZoneName:'short'}).format(new Date(data.roadMatrix.fetchedAt)):'';
 return `<div class="road-status ${roadLoad.error?'has-error':''}" role="status"><div><strong>${roadLoad.busy?esc(roadLoad.message):roadLoad.error?'Road routing needs attention':ready&&!pending?'Road routes ready':'Loading road routes…'}</strong><p>${roadLoad.error?esc(roadLoad.error):ready?'Driving estimates use the car-road network. Queried '+esc(queried)+'. No live traffic.':'Stops without road travel times stay unscheduled.'}</p></div><button class="text-button" data-action="refresh-roads" ${roadLoad.busy?'disabled':''}>${roadLoad.error?'Retry road routes':'Refresh roads'}</button></div>`;
}
function mapPanel(){
 if(!data.geographic)return illustrativeMapPanel();
 const shown=data.crews.some(crew=>crew.id===state.mapCrew)?state.mapCrew:'all',visibleJobs=ops.mapJobs().filter(job=>shown==='all'||job.crew===shown),count=visibleJobs.filter(hasCoordinates).length,shownRoutes=plan.routes.filter(route=>shown==='all'||route.crewId===shown),showRoutes=state.showRoadRoutes!==false;
 return `<section class="panel street-map-panel" aria-labelledby="territory-title"><div class="panel-header map-header"><div><h2 id="territory-title">Your service territory</h2><p class="panel-subtitle">${esc(data.area)} · ${count} of ${visibleJobs.length} locations mapped · ${shownRoutes.reduce((sum,route)=>sum+route.stops.length,0)} scheduled stops</p></div><div class="street-map-actions"><button class="button primary" data-action="optimize" ${!plan.roadReady?'disabled':''}>${state.optimized?'Recalculate routes':'Optimize routes'}</button><button class="text-button" data-action="connections" aria-pressed="${showRoutes}">${showRoutes?'Hide':'Show'} road routes</button></div></div>${ops.mapToggle()}<div class="map-crew-filter"><label for="map-crew">Show route</label><select id="map-crew"><option value="all" ${shown==='all'?'selected':''}>All crews</option>${data.crews.map(crew=>`<option value="${esc(crew.id)}" ${shown===crew.id?'selected':''}>${esc(crew.name)}</option>`).join('')}</select><span>Scheduled stops are shown first. Use the day toggle to include unscheduled visits.</span></div><div id="street-map" class="street-map" role="region" aria-label="Street map with road-following crew routes and customer stops"></div>${roadStatus()}<div class="map-bottom"><div class="map-legend">${data.crews.map((crew,index)=>`<span class="legend-entry"><i class="legend-dot crew-color-${index%12}"></i>${esc(crew.name)}</span>`).join('')}<span class="legend-entry"><i class="legend-dot pending"></i>Unscheduled</span></div><span>Customer coordinates · Mock customers</span></div><div class="map-source-note">Routes end at nearby road-access points for the supplied coordinates. The crew base is ${data.depot.locationSource?.startsWith('Assumed')?'an assumed service-area center; review it in Business settings.':'owner-entered.'} <a href="https://routing.openstreetmap.de/about.html" target="_blank" rel="noopener noreferrer">Routing: OSRM / FOSSGIS</a> · <a href="https://www.openstreetmap.org/fixthemap" target="_blank" rel="noopener noreferrer">Report a map issue</a></div></section>`;
}

function weatherPanel(){if(!data.geographic)return '';return '<section class="panel weather-panel" aria-labelledby="weather-title"><div class="panel-header"><div><h2 id="weather-title">Weather for the work ahead</h2><p class="panel-subtitle">Forecast near the center of your customer territory · Internet connection required</p></div></div><div id="weather-content"></div></section>';}
function stopFor(id){const job=getJob(id),scoped=job?.serviceDate&&job.serviceDate!==ops.selectedDate()?planLawnDay(workspaceForDay(data,job.serviceDate),false):plan;return scoped.routes.flatMap(route=>route.stops).find(stop=>stop.id===id);}
function status(job){if(isClientArchived(data,job))return '<span class="status needs-review">Archived client</span>';if(job.status==='completed'&&services(job).some(service=>!job.completedServices?.includes(service)))return '<span class="status needs-review">Partial work</span>';if(job.status==='planned'&&!job.serviceDate)return '<span class="status needs-review">Unscheduled</span>';if(job.status==='planned'&&!stopFor(job.id))return '<span class="status needs-review">Needs scheduling</span>';const labels={planned:'Scheduled',working:'On site',completed:'Completed',skipped:'Skipped'};return `<span class="status ${esc(job.status)}">${labels[job.status]||'Needs review'}</span>`;}
function serviceTags(job,completed=false){return `<span class="service-tags">${(completed?job.completedServices||[]:services(job)).map(s=>`<span class="service-tag">${s}</span>`).join('')}</span>`;}
function context(){return `<div class="context-line"><span>${icon('calendar')}<strong>${dateText(ops.selectedDate())}</strong><span>· ${plan.jobs.length} visits on this day · ${data.crews.length} crews</span></span><span>${icon('clock')}Demo day clock · ${clockLabel(data.now)}</span></div>`;}
function metric(label,value,foot,glyph,featured=false){return `<article class="metric ${featured?'featured':''}"><div class="metric-top"><span>${label}</span><span class="metric-icon">${icon(glyph)}</span></div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></article>`;}
function metrics(){return `<section class="metrics" aria-label="Day snapshot">${metric('Jobs on this day',plan.jobs.length,`<strong>${plan.completed} completed</strong><span>· ${plan.working} on site</span><span class="progress-dots" aria-hidden="true">${data.jobs.map(j=>`<i class="${j.status==='completed'?'done':''}"></i>`).join('')}</span>`,'clipboard',true)}${metric('Quoted day value',plan.quoted?money(plan.revenue):'Needs pricing',`<strong>${plan.quoted} priced visits</strong><span>· customer job prices</span>`,'wallet')}${metric('Modeled job costs',data.geographic&&!plan.roadReady?'Await routing':money(plan.cost),`Labor, travel & allocated costs · ${Object.keys(plan.costs).length} of ${plan.jobs.length} routed`,'users')}${metric('Planned travel',data.geographic&&!plan.roadReady?'—':plan.travelMinutes+'<small>min</small>',`${state.optimized?'<strong>Route search applied</strong>':state.dayPlanApplied?'<strong>Day plan applied</strong>':'Saved-order baseline'}<span>· ${data.geographic?(plan.roadReady?'road driving estimates':'awaiting road times'):'sample times'}</span>`,'route')}</section>`;}

function mapSVG(){
 const width=1000/state.zoom,height=600/state.zoom,focus=state.selected&&getJob(state.selected),cx=focus?.x??500,cy=focus?.y??300;
 const vx=Math.max(0,Math.min(1000-width,cx-width/2)),vy=Math.max(0,Math.min(600-height,cy-height/2));
 const roads=[...Array.from({length:6},(_,i)=>`<path d="M${120+i*140} 0V600"/>`),...Array.from({length:5},(_,i)=>`<path d="M0 ${90+i*100}H1000"/>`)].join('');
 const blocks=Array.from({length:7},(_,x)=>Array.from({length:5},(_,y)=>`<rect x="${22+x*142}" y="${20+y*102}" width="${73+(x+y)%3*12}" height="${42+(x+y)%2*12}" rx="5" fill="${(x+y)%3===0?'#dce7ce':'#e5e8dd'}"/>`).join('')).join('');
 const routes=plan.routes.map(route=>{let previous=data.depot;const commands=[`M${previous.x} ${previous.y}`];for(const stop of route.stops){const job=getJob(stop.id);commands.push(`L${job.x} ${previous.y}L${job.x} ${job.y}`);previous=job;}if(route.stops.length)commands.push(`L${data.depot.x} ${previous.y}L${data.depot.x} ${data.depot.y}`);return `<path class="route-path ${route.crewId==='B'?'route-b':''}" d="${commands.join(' ')}" stroke="${route.crewId==='B'?'#6683a8':'#63865b'}"/>`;}).join('');
 const pins=data.jobs.filter(hasPin).map(job=>{const route=plan.routes.find(r=>r.crewId===job.crew),number=(route?.stops.findIndex(s=>s.id===job.id)??-1)+1,color=job.crew==='B'?'#5b79a1':'#3c694c';return `<g class="job-pin" role="button" tabindex="0" data-pin="${esc(job.id)}" aria-label="${esc(job.name)}, ${esc(job.address)}, ${job.status}"><circle cx="${job.x}" cy="${job.y}" r="${job.status==='working'?25:19}" fill="${job.status==='working'?'#d9e8ca':'#ffffff'}" stroke="${color}" stroke-width="${state.selected===job.id?4:2}"/><circle cx="${job.x}" cy="${job.y}" r="15" fill="${job.status==='completed'?'#9bb18b':color}"/><text class="pin-number" x="${job.x}" y="${job.y}">${job.status==='completed'?'✓':number||'?'}</text></g>`;}).join('');
 return `<svg class="map-svg" viewBox="${vx} ${vy} ${width} ${height}" preserveAspectRatio="xMidYMid meet" role="group" aria-label="Illustrative demo service map. Select numbered stops for details."><rect width="1000" height="600" fill="#eff1e8"/>${blocks}<path d="M595 -40C510 100 640 170 558 310s-30 240 35 340" fill="none" stroke="#d2e3df" stroke-width="50"/><rect x="295" y="74" width="140" height="117" rx="29" fill="#d7e6ca"/><rect x="735" y="330" width="92" height="115" rx="24" fill="#dce8d1"/><g stroke="#fffef9" stroke-width="15" fill="none">${roads}</g><g stroke="#d9dfd1" stroke-width="1" fill="none">${roads}</g><text class="road-name" x="275" y="102">MEADOW AVENUE</text><text class="road-name" x="650" y="302">LAKEVIEW ROAD</text><text class="road-name" x="230" y="502">GREENWAY</text><text class="area-name" x="300" y="148">WEST PARK</text><text class="area-name" x="715" y="80">BROOKFIELD</text>${routes}<g><rect x="${data.depot.x-18}" y="${data.depot.y-17}" width="36" height="34" rx="7" fill="#fdfefa" stroke="#9ba988" stroke-width="2"/><path d="m${data.depot.x-10} ${data.depot.y-2} 10-8 10 8v10h-20Z" fill="#8a9d72"/></g>${pins}</svg>`;
}
function illustrativeMapPanel(){const selected=state.selected&&getJob(state.selected),stop=selected&&stopFor(selected.id);return `<section class="panel map-panel" aria-labelledby="territory-title"><div class="panel-header map-header"><div><h2 id="territory-title">Today’s territory</h2><p class="panel-subtitle">${data.area} · ${plan.unassigned.length?plan.unassigned.length+' unassigned':data.jobs.length+' visits on the map'}</p></div><button class="button ${state.optimized?'secondary':'primary'}" data-action="optimize">${icon('route')}${state.optimized?'Recalculate routes':'Optimize routes'}</button></div><div class="map-stage">${mapSVG()}<div class="map-weather">${icon('sun')}<div><strong>62° · Partly cloudy</strong><small>Sample forecast · Rain possible after 3pm</small></div></div><div class="map-controls" aria-label="Map zoom"><button data-zoom="in" aria-label="Zoom in">+</button><button data-zoom="out" aria-label="Zoom out">−</button><button data-zoom="reset" aria-label="Show all stops">⌖</button></div>${selected?`<div class="map-selected"><p class="eyebrow">${getCrew(selected.crew)?.name||'UNASSIGNED'}</p><strong>${esc(selected.name)}</strong><p>${stop?clockLabel(stop.start)+' – '+clockLabel(stop.end):'Needs a route assignment'}</p><button class="text-button" data-job="${esc(selected.id)}">View job details ${icon('arrow')}</button></div>`:''}<span class="map-caption">Illustrative map · Sample travel times</span></div><div class="map-bottom"><div class="map-legend"><span class="legend-entry"><i class="legend-dot"></i>Willow crew</span><span class="legend-entry"><i class="legend-dot blue"></i>Clover crew</span><span class="legend-entry"><i class="legend-dot depot"></i>Base</span></div><span>Check-in based progress</span></div></section>`;}
function crewMini(){return `<aside class="panel crew-panel" aria-label="Crew schedules"><div class="panel-header"><div><h2>Your crews, on track</h2><p class="panel-subtitle">Last reported progress · ${clockLabel(data.now)}</p></div><span class="small-count">${data.crews.length} crews</span></div>${plan.routes.map(route=>{const crew=getCrew(route.crewId),active=plan.jobs.find(j=>j.crew===crew.id&&j.status==='working'),upcoming=route.stops.filter(s=>getJob(s.id).status!=='completed').slice(0,3);return `<div class="crew-mini"><div class="crew-mini-heading"><span class="crew-avatar ${crew.id==='B'?'blue':''}">${esc(crew.name[0])}</span><div><strong>${crew.name}</strong><small>${crew.members} people · ${route.stops.length} visits</small></div><span class="status ${active?'working':''}">${active?'On site':'Ready'}</span></div>${upcoming.map(s=>{const job=getJob(s.id);return `<div class="mini-stop"><i class="stop-dot ${crew.id==='B'?'blue':''}"></i><div><strong>${esc(job.name)}</strong><small>${services(job).join(' + ')} · ${job.minutes??'—'} min</small></div><time>${clockLabel(s.start)}</time></div>`;}).join('')||'<p class="field-hint">No scheduled visits for this day.</p>'}<button class="text-button" data-crew="${crew.id}">View crew’s ${route.stops.length} stops ${icon('arrow')}</button></div>`;}).join('')}</aside>`;}
function insight(){const saved=baseline.travelMinutes-plan.travelMinutes,cost=Number(baseline.travelCost)-Number(plan.travelCost);if(plan.unassigned.length)return `<div class="plan-insight warning">${icon('help')}<div><strong>${plan.unassigned.length} visit${plan.unassigned.length===1?' needs':'s need'} a little attention.</strong><p>Review service-time estimates, crew assignments and available time. Unassigned jobs are listed below.</p></div><a class="button secondary" href="#jobs">Review jobs ${icon('arrow')}</a></div>`;return `<div class="plan-insight">${icon('leaf')}<div><strong>${state.optimized?(saved>0?`${saved} fewer travel minutes. ${money(cost)} less modeled travel cost.`:'Your route search is ready to review.'):'A little planning can go a long way.'}</strong><p>${state.optimized?'Compared with spreadsheet order, for the same jobs and crews. Travel estimates; estimated benefits.':'Compare the spreadsheet order with a route search, while keeping reported visits in place.'}</p></div><button class="button secondary" data-action="${state.optimized?'baseline':'optimize'}">${state.optimized?'View baseline':'Find a clearer route'} ${icon('arrow')}</button></div>`;}

function filteredJobs(){const query=state.search.toLowerCase().trim();return data.jobs.filter(job=>ops.filterClient(job)&&(!query||[job.name,job.address,job.id].join(' ').toLowerCase().includes(query))&&(state.filter==='all'||state.filter==='attention'&&(!job.serviceDate||job.price===null||job.minutes===null||plan.unassigned.some(issue=>issue.id===job.id))||state.filter===job.status));}
let pendingDayPlan=null;
function suggestedPriceCell(job){
 const suggestion=suggestJobPrice(data,job,plan);
 if(job.price!==null&&job.price!==undefined)return money(job.price)+(suggestion.ready&&job.status==='planned'?'<span class="subtext">Suggested '+money(suggestion.suggested)+'</span>':'');
 return suggestion.ready?'<button class="price-suggestion-link" data-price="'+esc(job.id)+'"><strong>'+money(suggestion.suggested)+'</strong><span>Suggested · review ↗</span></button>':'<button class="text-button" data-price="'+esc(job.id)+'">Set price ↗</button><span class="subtext">'+esc(suggestion.reason)+'</span>';
}
function dayPlanningPanel(){
 const ready=plan.jobs.filter(job=>job.status==='planned'&&suggestJobPrice(data,job,plan).ready).length;
 return '<section class="day-planning-panel" aria-labelledby="day-planning-title"><div><p class="eyebrow">PUT THE DAY TO WORK</p><h2 id="day-planning-title">The right jobs. A clearer route.</h2><p>'+ready+' visits have price suggestions. Build a plan within daily limits, then compare labor budgets and road travel.</p><small>Checks service time, road access, customer windows, breaks and return to base. Reported work stays with its crew.</small></div><div class="planning-actions"><button class="button primary" data-action="build-day-plan" '+(data.geographic&&!plan.roadReady?'disabled':'')+'>'+icon('spark')+'Build day plan</button>'+(state.dayPlanBackup?'<button class="text-button" data-action="undo-day-plan">Undo last applied plan</button>':'')+'</div></section>';
}
function openDayPlan(){
 const dialog=document.getElementById('day-plan-dialog'),body=document.getElementById('day-plan-content');
 document.getElementById('day-plan-error').textContent='';document.getElementById('day-plan-apply').disabled=true;
 body.innerHTML='<div class="weather-loading" role="status">Comparing job fit, crew assignments and driving time…</div>';dialog.showModal();
 setTimeout(()=>{
  try{
   pendingDayPlan=recommendLawnDay(dayData());const proposal=pendingDayPlan,scheduled=proposal.plan.routes.reduce((sum,route)=>sum+route.stops.length,0),currentCount=proposal.current.routes.reduce((sum,route)=>sum+route.stops.length,0),view={...dayData(),jobs:proposal.jobs},grouped=new Map();
   for(const issue of proposal.plan.unassigned)grouped.set(issue.reason,(grouped.get(issue.reason)||0)+1);
   const suggestions=proposal.jobs.map(job=>suggestJobPrice(view,job,proposal.plan)),suggestedValue=proposal.plan.routes.flatMap(route=>route.stops).reduce((sum,stop)=>{const suggestion=suggestions[proposal.jobs.findIndex(job=>job.id===stop.id)];return sum+(suggestion.ready?Number(suggestion.suggested):0);},0);
   body.innerHTML='<div class="day-plan-summary"><div><strong>'+scheduled+' / '+plan.jobs.length+'</strong><span>visits fit · '+currentCount+' in saved order</span></div><div><strong>'+proposal.plan.travelMinutes+' min</strong><span>road driving · return included</span></div><div><strong>'+money(suggestedValue.toFixed(2))+'</strong><span>suggested scheduled value · before tax</span></div></div><p class="day-plan-explanation">'+proposal.changes.length+' proposed crew changes. Prices remain suggestions until the operator reviews them. The search prioritizes job fit, then modeled cost and road travel. It does not guarantee a global optimum.</p>'+proposal.plan.routes.map(route=>{const crew=getCrew(route.crewId);return '<section class="day-plan-crew"><h3>'+esc(crew.name)+' <span>'+route.stops.length+' visits · return '+clockLabel(route.finish)+'</span></h3><div class="table-scroll"><table><thead><tr><th>Stop / customer</th><th>Visit window</th><th>Suggested price</th><th>Reviewed price</th></tr></thead><tbody>'+route.stops.map((stop,index)=>{const job=proposal.jobs.find(job=>job.id===stop.id),suggestion=suggestJobPrice(view,job,proposal.plan);return '<tr><td><strong>'+String(index+1)+'. '+esc(job.name)+'</strong><span class="subtext">'+esc(job.address)+'</span></td><td>'+clockLabel(stop.start)+' – '+clockLabel(stop.end)+'</td><td>'+(suggestion.ready?money(suggestion.suggested):'Needs review')+'</td><td>'+(job.price===null?'Not reviewed':money(job.price))+'</td></tr>';}).join('')+'</tbody></table></div></section>';}).join('')+(grouped.size?'<div class="notice amber"><strong>'+proposal.plan.unassigned.length+' visits remain outside this plan</strong><ul>'+[...grouped].map(([reason,count])=>'<li>'+count+' · '+esc(reason)+'</li>').join('')+'</ul></div>':'')+'<p class="field-hint">Based on current service estimates, crew settings and road times without live traffic. Weather remains a separate owner review. Suggested job values are not payments or guaranteed profit.</p>';
   document.getElementById('day-plan-apply').disabled=data.geographic&&!proposal.plan.roadReady;
  }catch(error){pendingDayPlan=null;body.textContent='The day plan could not be built.';document.getElementById('day-plan-error').textContent=error.message;}
 },0);
}
function applyDayPlan(){
 if(!pendingDayPlan)return;
 if(pendingDayPlan.fingerprint!==planningFingerprint(dayData())){document.getElementById('day-plan-dialog').close();openDayPlan();document.getElementById('day-plan-error').textContent='Job details or road data changed. Review the refreshed proposal.';return;}
 state.dayPlanBackup={order:data.jobs.map(job=>job.id),crews:Object.fromEntries(data.jobs.map(job=>[job.id,job.crew])),ranks:Object.fromEntries(data.jobs.map(job=>[job.id,job.routeOrder])),optimized:state.optimized,applied:!!state.dayPlanApplied};
 data.jobs=pendingDayPlan.jobs;state.optimized=false;state.dayPlanApplied=true;pendingDayPlan=null;
 document.getElementById('day-plan-dialog').close();save();render();toast('Day plan applied. Crew assignments and stop order are updated; reviewed prices are preserved.');
}
function undoDayPlan(){
 const backup=state.dayPlanBackup;if(!backup)return;
 const rank=new Map(backup.order.map((id,index)=>[id,index]));
 for(const job of data.jobs)if(job.status==='planned'&&backup.crews[job.id])Object.assign(job,{crew:backup.crews[job.id],routeOrder:backup.ranks?.[job.id]});
 data.jobs.sort((a,b)=>(rank.get(a.id)??1e6)-(rank.get(b.id)??1e6));
 state.optimized=backup.optimized;state.dayPlanApplied=backup.applied;delete state.dayPlanBackup;save();render();toast('Previous job order and unstarted crew assignments restored.');
}
document.getElementById('day-plan-apply').addEventListener('click',applyDayPlan);

function jobsTable(jobs){return ops.jobsTable(jobs);}
function jobsSection(full=false){return `<section><div class="section-heading"><div><h2>${full?'Your clients & visits':'Jobs for '+dateText(ops.selectedDate())} <span class="small-count">${full?activeClients(data).length:plan.jobs.length}</span></h2><p>${full?'Manage active, new, existing and archived clients.':'This day’s visits. Other dates and unscheduled work stay in the client directory.'}</p></div>${full?'<button class="text-button" data-action="export">Export day '+icon('download')+'</button>':'<a class="text-button" href="#jobs">Manage clients '+icon('arrow')+'</a>'}</div>${full?ops.clientToolbar()+bulkPricing.undoNotice()+`<div class="filters"><div class="search"><label class="sr-only" for="job-search">Search customers or addresses</label>${icon('search')}<input id="job-search" type="search" placeholder="Search customers or addresses" value="${esc(state.search)}"></div><label class="sr-only" for="job-filter">Filter job status</label><select id="job-filter">${[['all','All visits'],['planned','Not started'],['working','On site'],['completed','Completed'],['attention','Needs attention']].map(([value,label])=>`<option value="${value}" ${value===state.filter?'selected':''}>${label}</option>`).join('')}</select></div>`:''}<div class="panel" id="jobs-table">${jobsTable(full?filteredJobs():plan.jobs.slice(0,8))}</div></section>`;}
function pricingPage(){if(!data.jobs.length)return `<section class="panel auth-empty-workspace"><h2>A confident quote starts with a job.</h2><p>Add your first customer and requested services to calculate a price from your labor, travel, and material costs.</p><button class="button primary" data-business="new-job">Add your first job</button></section>`;let job=getJob(state.quoteJob)||data.jobs[0];state.quoteJob=job.id;const crew=getCrew(job.crew)||data.crews[0],suggestion=jobPriceSuggestion(data,job,{optimized:state.optimized,optimizedDate:ops.selectedDate()}),travel=suggestion.ready?suggestion.travelMinutes:(job.quoteInputs?.travelMinutes??0);return bulkPricing.panelHTML()+`<div class="pricing-layout"><div><section class="panel pricing-main"><div class="pricing-selector"><label for="quote-job">Price a customer visit</label><select id="quote-job">${data.jobs.map(j=>`<option value="${esc(j.id)}" ${j.id===job.id?'selected':''}>${esc(j.name)} · ${services(j).join(' + ')}</option>`).join('')}</select></div><div class="price-job-heading"><span class="customer-avatar">${esc(initials(job.name))}</span><div><strong>${esc(job.name)}</strong><small>${esc(job.address)}${job.areaSqft?' · '+job.areaSqft.toLocaleString()+' sq ft (demo)':''}</small></div></div><form id="quote-form" class="price-fields"><div class="form-grid"><div><label class="field-label" for="quote-crew">Crew</label><select id="quote-crew" ${['working','completed'].includes(job.status)?'disabled':''}>${data.crews.map(c=>`<option value="${c.id}" ${c.id===crew.id?'selected':''}>${c.name} · ${c.members} people</option>`).join('')}</select></div><div><label class="field-label" for="quote-minutes">Service time (crew minutes)</label><input id="quote-minutes" type="number" min="1" max="600" value="${job.minutes??''}" required></div><div><label class="field-label" for="quote-travel">Allocated travel / wait (min)</label><input id="quote-travel" type="number" min="0" max="1000" value="${travel}" required></div><div><label class="field-label" for="quote-materials">Materials & supplies ($)</label><input id="quote-materials" type="number" min="0" max="10000" step="0.01" value="${job.materials||'0.00'}" required></div></div><div class="form-section"><h3>Make the margin intentional.</h3><p>Target margin is a share of the suggested price. All rates here are editable demo assumptions.</p></div><div class="form-grid"><div><label class="field-label" for="quote-margin">Target modeled margin (%)</label><input id="quote-margin" type="number" min="0" max="95" step="0.1" value="${(job.quoteInputs?.marginBps??data.settings.marginBps)/100}" required></div><div><label class="field-label" for="quote-minimum">Minimum quote ($)</label><input id="quote-minimum" type="number" min="0" max="10000" step="0.01" value="${job.quoteInputs?.minimum??data.settings.minimumPrice}" required></div></div><p class="field-hint">Cost rates come from Business settings. Travel allocation follows the current demo plan; the last visit includes the return trip. ${suggestion.ready?(suggestion.basis==='Current day route'?'Travel comes from this visit’s service-day route.':suggestion.basis==='Saved travel allowance'?'Using this job’s saved travel allowance.':'Unscheduled work uses a return trip from the crew base. Review it when the route is planned.'):'Travel needs review. Enter a travel allowance before relying on the suggestion.'} Crew size changes cost, with service-time estimates reviewed separately.</p><p class="form-error" id="quote-error" role="alert"></p></form></section><section class="panel comparison-panel"><div class="panel-header"><div><h2>A little history helps</h2><p class="panel-subtitle">Comparable visits · Fictional job-history examples</p></div></div><div class="table-scroll"><table><thead><tr><th>Example completed visit</th><th>Time</th><th>Price</th><th>Modeled cost</th></tr></thead><tbody>${data.history.map(h=>`<tr><td>${esc(h.label)}</td><td>${h.minutes} min</td><td>${money(h.price)}</td><td>${money(h.cost)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel comparison-panel"><div class="panel-header"><div><h2>Market comparison notes</h2><p class="panel-subtitle">Compare matching services and property conditions.</p></div><button class="text-button" data-action="add-benchmark">Add comparison +</button></div>${data.benchmarks.map(b=>`<div class="benchmark-row"><div>${esc(b.label)}<small>${esc(b.note)}</small></div><strong>${money(b.price)}</strong></div>`).join('')}<div class="table-foot">Sample comparisons are fictional. Owner-entered sources are not independently verified.</div></section></div><aside class="pricing-sidebar"><div class="quote-result"><p class="eyebrow">COST-BASED PRICE SUGGESTION</p><div class="quote-value" id="quote-suggested">—</div><p class="quote-caption">Before tax · Based on the costs and target you entered</p><div class="quote-breakdown" id="quote-breakdown"></div><label class="field-label" for="quote-final">Owner-reviewed customer job price ($)</label><input id="quote-final" type="number" min="0" max="1000000" step="0.01" value="${job.price??''}" placeholder="Review a job price"><button class="button" id="quote-use">Use suggested price</button><button class="button" id="quote-save">Save reviewed job price ${icon('check')}</button></div><div class="price-note"><h3>Price the work. Learn from the cost.</h3><p>The saved job price is the amount used in this quote-based demo’s completion draft. Actual visit time updates modeled cost; it does not automatically add a labor charge.</p></div><div class="price-note"><h3>An estimate with its reasons.</h3><p id="quote-explanation"></p><p>These estimates cover modeled inputs, rather than complete business net profit. Similar work and market notes are context for owner review.</p></div></aside></div>`;}
function readQuote(){const form=document.getElementById('quote-form');if(!form.checkValidity())throw Error('Check the pricing inputs and their ranges');const crew=getCrew(document.getElementById('quote-crew').value);return {minutes:Number(document.getElementById('quote-minutes').value),travelMinutes:Number(document.getElementById('quote-travel').value),crew,materials:Number(document.getElementById('quote-materials').value).toFixed(2),marginBps:Math.round(Number(document.getElementById('quote-margin').value)*100),minimum:Number(document.getElementById('quote-minimum').value).toFixed(2)};}
function updateQuote(){try{const input=readQuote(),quote=quoteJob(input);document.getElementById('quote-suggested').textContent=money(quote.suggested,true);document.getElementById('quote-breakdown').innerHTML=[['On-site labor',quote.labor],['Travel & allocated wait',quote.travel],['Equipment',quote.equipment],['Materials',quote.materials],['Allocated overhead',quote.overhead],['Modeled job cost',quote.cost]].map(([label,value],i)=>`<div class="${i===5?'total':''}"><span>${label}</span><strong>${money(value,true)}</strong></div>`).join('');document.getElementById('quote-explanation').textContent=`${input.minutes} crew minutes × ${input.crew.members} people = ${(quote.workerMinutes/60).toFixed(2)} labor-hours. The suggestion targets ${input.marginBps/100}% margin on these modeled costs, subject to the minimum quote.`;document.getElementById('quote-error').textContent='';return quote;}catch(error){document.getElementById('quote-error').textContent=error.message;return null;}}

function crewPage(){const crew=getCrew(state.crew)||data.crews[0],route=plan.routes.find(r=>r.crewId===crew.id),jobs=[...route.stops.map(s=>getJob(s.id)),...route.unassigned.map(s=>getJob(s.id))];return `<div class="crew-page-top"><div class="crew-tabs" aria-label="Choose demo crew">${data.crews.map(c=>`<button data-crew-select="${c.id}" aria-pressed="${c.id===crew.id}">${c.name}</button>`).join('')}</div><button class="button secondary" data-map-crew="${crew.id}">View road route ${icon('route')}</button><p class="crew-note">Crew preview · Check-ins update this browser’s demo<br>${dateText(ops.selectedDate())} · Demo clock ${clockLabel(data.now)}</p></div>${jobs.map((job,i)=>{const stop=stopFor(job.id),isWorking=job.status==='working',finished=job.status==='completed';return `<article class="panel crew-job-card ${isWorking?'active-job':''}"><div class="crew-job-top"><p class="eyebrow">STOP ${i+1} · ${stop?clockLabel(stop.start)+' – '+clockLabel(stop.end):'NEEDS SCHEDULING'}</p>${status(job)}</div><h2 class="crew-job-address">${esc(job.address)}</h2><p>${esc(job.name)} · ${esc(job.notes||'No additional access notes.')}</p><div class="crew-job-details"><span>${icon('clock')}${finished?(job.actualEnd-job.actualStart)+' min reported':job.minutes===null?'Needs service-time estimate':job.minutes+' min estimated'}</span><span>${icon('users')}${crew.members} people</span>${finished?`<span>${icon('check')}Finished ${clockLabel(job.actualEnd)}</span>`:''}</div><div class="crew-job-bottom">${serviceTags(job,finished)}${finished?'<span class="field-hint">Completion recorded</span>':isWorking?`<button class="button primary" data-finish="${esc(job.id)}">Finish job ${icon('check')}</button>`:`<button class="button secondary" data-start="${esc(job.id)}" ${!hasPin(job)||!Number.isInteger(job.minutes)||job.serviceDate!==(data.clockDate||data.date)?'disabled':''}>Start job ${icon('play')}</button>`}</div></article>`;}).join('')||'<div class="panel empty-state"><strong>No visits assigned</strong>Assign a customer job to this crew to get started.</div>'}`;}

function reviewPage(){const completed=plan.jobs.filter(j=>j.status==='completed'),value=completed.filter(j=>j.price!==null).reduce((sum,j)=>sum+Number(j.price),0),minutes=completed.filter(j=>Number.isInteger(j.actualStart)&&Number.isInteger(j.actualEnd)).reduce((sum,j)=>sum+j.actualEnd-j.actualStart,0);let ready=0;for(const job of completed){try{completionDraft(job,job.serviceDate||ops.selectedDate());ready++;}catch{}}
 return `<section class="review-banner"><div><h2>${completed.length} jobs done. A good day taking shape.</h2><p>Review the reported work and job prices, then prepare a personal finish for your customers.</p></div><button class="button" data-action="emails">${icon('mail')}Preview ${ready} completion messages</button></section><section class="review-cards">${metric('Completed job value',money(value),`${completed.filter(j=>j.price!==null).length} priced completed visits · not cash received`,'wallet')}${metric('Reported on-site time',duration(minutes),'Elapsed crew time · worker-hours account for crew size','clock')}${metric('Completion drafts ready',ready,`${completed.length-ready} completed visits need information`,'mail')}</section><div class="notice">Messages include confirmed completed services and the reviewed job price. Email delivery is not connected; you can preview and download drafts.</div><section class="panel"><div class="panel-header"><div><h2>The work, reconciled</h2><p class="panel-subtitle">Actual service time alongside current modeled costs</p></div><button class="text-button" data-action="export">Export day ${icon('download')}</button></div><div class="table-scroll"><table><thead><tr><th>Customer</th><th>Completed services</th><th>Reported time</th><th>Job value</th><th>Modeled cost</th><th>Message</th></tr></thead><tbody>${completed.map(j=>{let emailReady=true;try{completionDraft(j,data.date);}catch{emailReady=false;}return `<tr><td><button class="customer-name" data-job="${esc(j.id)}">${esc(j.name)}</button><span class="subtext">${esc(j.address)}</span></td><td>${serviceTags(j,true)}</td><td>${j.actualEnd-j.actualStart} min<span class="subtext">${((j.actualEnd-j.actualStart)*getCrew(j.crew).members/60).toFixed(2)} labor-hours</span></td><td>${money(j.price)}</td><td>${plan.costs[j.id]?money(plan.costs[j.id].cost):'Needs route'}</td><td><span class="status ${emailReady?'':'review'}">${emailReady?'Draft ready':'Needs review'}</span></td></tr>`;}).join('')||'<tr><td colspan="6"><div class="empty-state"><strong>Your day is still growing.</strong>Finish a visit in Crew view to review its work and prepare a message.</div></td></tr>'}</tbody></table></div><div class="table-foot">Costs include modeled travel and allocation assumptions. Job timers alone do not establish total payroll or actual driving time.</div></section>`;}

function render(){
 if(!data)return;
 landscape.initialize(data);
 destroyStreetMap();destroyStreetMap=()=>{};baseline=planLawnDay(dayData(),false);plan=state.optimized?planLawnDay(dayData(),true):baseline;
 const current=page(),info=pageInfo[current];document.getElementById('breadcrumb-current').textContent=info[0];document.getElementById('page-eyebrow').textContent=info[1];document.getElementById('page-title').textContent=info[2];document.getElementById('page-description').textContent=info[3];document.getElementById('nav-job-count').textContent=activeClients(data).length;
 document.querySelectorAll('[data-page]').forEach(link=>{if(link.dataset.page===current||(current==='project'&&link.dataset.page==='projects'))link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});
 content.innerHTML=current==='week'?landscape.schedulePage():current==='today'?landscape.todayPage():current==='projects'?landscape.projectsPage():current==='project'?landscape.projectPage():current==='planning'?ops.weekPage():current==='jobs'?context()+jobsSection(true):current==='pricing'?pricingPage():current==='crew'?landscape.crewsPage():reviewPage();
 if(current==='project'){const project=data.landscape.projects.find(item=>item.id===location.hash.slice('#project/'.length));if(project){document.getElementById('page-title').textContent=project.name;document.getElementById('page-description').textContent=project.address;}}
 document.body.dataset.view=current;business.paintSaveState();business.paintIdentity();
 document.getElementById('ops-mobile-menu').hidden=true;document.getElementById('ops-mobile-more').setAttribute('aria-expanded','false');
 if(current==='pricing'&&data.jobs.length){const layout=content.querySelector('.pricing-layout'),selector=content.querySelector('.pricing-selector');if(layout&&selector){selector.classList.add('ops-pricing-selector');layout.before(selector);}updateQuote();}
 if(current==='today'&&data.geographic){const mapEl=document.getElementById('street-map');if(mapEl)destroyStreetMap=mountStreetMap(mapEl,{jobs:ops.mapJobs(),routingWorkspace:data,routes:plan.routes,depot:data.depot,roadMatrix:data.roadMatrix,roadShapes:data.roadShapes||{},crews:data.crews,crewFilter:state.mapCrew||'all',showRoutes:state.showRoadRoutes!==false,onOpen:openJob});const weatherEl=document.getElementById('weather-content'),point=coordinateCenter(plan.jobs)||data.depot;if(weatherEl&&hasCoordinates(point))mountWeather(weatherEl,point,{serviceDate:ops.selectedDate(),label:data.area});}
 if(data.geographic)queueMicrotask(()=>ensureRoadRouting());
}
function go(view){if(page()===view)render();else location.hash=view;}

function openJob(id){const job=getJob(id);if(!job)return;const stop=stopFor(id),crew=getCrew(job.crew);document.getElementById('job-content').innerHTML=`<div class="dialog-top"><div><p class="eyebrow">CUSTOMER VISIT · ${esc(job.id)}</p><h2 id="job-title">A closer look at the job.</h2></div><button class="icon-button" data-close aria-label="Close job details">${icon('close')}</button></div><div class="detail-customer"><span class="customer-avatar">${esc(initials(job.name))}</span><div><strong>${esc(job.name)}</strong><p>${esc(job.address)}</p></div></div>${status(job)}${job.status==='completed'&&services(job).some(s=>!job.completedServices?.includes(s))&&!job.completionPriceReviewed?'<div class="notice amber">Some requested services were not completed. Review the customer job price before preparing a message.</div>':''}<div class="detail-row"><span>Requested services</span><strong>${services(job).join(' + ')}</strong></div><div class="detail-row"><span>Planned window</span><strong>${stop?clockLabel(stop.start)+' – '+clockLabel(stop.end):'Needs routing information'}</strong></div><div class="detail-row"><span>Contact</span><strong>${esc(job.email||'Email needed')}<br>${esc(job.phone||'')}</strong></div><div class="detail-row"><span>Estimate source</span><strong>${esc(job.estimateSource)}</strong></div><div class="detail-row"><span>Source record</span><strong>${esc(job.source)}</strong></div>${job.status==='completed'?`<div class="detail-row"><span>Actually completed</span><strong>${(job.completedServices||[]).join(' + ')}<br>${clockLabel(job.actualStart)} – ${clockLabel(job.actualEnd)}</strong></div>`:''}<form id="job-edit-form" class="job-detail-form" data-id="${esc(job.id)}"><div class="form-grid"><div><label class="field-label" for="job-minutes">Estimated crew minutes</label><input id="job-minutes" type="number" min="1" max="600" value="${job.minutes??''}" placeholder="Needs estimate"></div><div><label class="field-label" for="job-price">Reviewed job price ($)</label><input id="job-price" type="number" min="0" max="1000000" step="0.01" value="${job.price??''}" placeholder="Needs price"></div></div><label class="field-label" for="job-crew">Assigned crew</label><select id="job-crew" ${job.status!=='planned'?'disabled':''}>${data.crews.map(c=>`<option value="${c.id}" ${c.id===job.crew?'selected':''}>${c.name}</option>`).join('')}</select><div ${data.geographic?'hidden':''}><label class="field-label" for="job-zone">Sample map pin</label><select id="job-zone"><option value="current">${hasPin(job)?'Keep current demo pin':'Choose an area to place this demo visit'}</option><option value="west">West Park</option><option value="central">Central Greenway</option><option value="east">East Brookfield</option><option value="lakeside">Lakeview</option></select><p class="field-hint">These are illustrative demo locations. Real address lookup is not connected.</p></div><div class="form-grid"><div><label class="field-label" for="job-latitude">Latitude</label><input id="job-latitude" type="number" min="-90" max="90" step="any" value="${job.latitude??''}"></div><div><label class="field-label" for="job-longitude">Longitude</label><input id="job-longitude" type="number" min="-180" max="180" step="any" value="${job.longitude??''}"></div></div><p class="field-hint">${esc(job.locationSource||'Supply latitude and longitude for street-map placement.')}</p><p id="job-error" class="form-error" role="alert"></p><div class="dialog-actions"><button type="button" class="button secondary" data-price="${esc(job.id)}">Open Price studio</button><button class="button primary" type="submit">Save details</button></div></form><div class="detail-actions">${job.status==='planned'?`<button class="text-button" data-start="${esc(job.id)}">Start job ${icon('play')}</button>`:job.status==='working'?`<button class="button primary" data-finish="${esc(job.id)}">Finish job ${icon('check')}</button>`:''}</div>`;ops.decorateJobDialog(job);document.getElementById('job-dialog').showModal();}
function openFinish(id){const job=getJob(id);if(job?.status!=='working')return;document.querySelectorAll('dialog[open]').forEach(d=>d.close());document.getElementById('finish-id').value=id;document.getElementById('finish-customer').textContent=job.name+' · '+job.address;document.getElementById('finish-start').value=clockInput(job.actualStart);document.getElementById('finish-end').value=clockInput(Math.min(1439,Math.max(data.now,job.actualStart+job.minutes)));document.getElementById('finish-services').innerHTML=services(job).map(s=>`<label class="check-label"><input type="checkbox" name="completed-service" value="${s}" checked>${s}</label>`).join('');document.getElementById('finish-error').textContent='';document.getElementById('finish-dialog').showModal();}
function start(id){try{startLawnJob(data,id);save();document.getElementById('job-dialog').close();render();toast('Job started. The crew’s reported stop is up to date.');}catch(error){toast(error.message);}}

function openSettings(){ops.openSettings();}
function openEmails(){activeDrafts=[];const errors=[];for(const job of plan.jobs.filter(j=>j.status==='completed')){try{activeDrafts.push(completionDraft(job,data.date));}catch(error){errors.push(job.name+': '+error.message);}}document.getElementById('email-content').innerHTML=(errors.length?`<div class="notice amber">${errors.map(esc).join('<br>')}</div>`:'')+(activeDrafts.length?`<div class="email-selector"><label class="field-label" for="email-select">Review a customer message</label><select id="email-select">${activeDrafts.map((d,i)=>`<option value="${i}">${esc(d.to)}</option>`).join('')}</select></div><div id="email-preview"></div>`:'<div class="empty-state"><strong>No messages ready yet</strong>Complete a visit and review its email, services and price.</div>');document.getElementById('draft-download').disabled=!activeDrafts.length;if(activeDrafts.length)renderEmail(0);document.getElementById('emails-dialog').showModal();}
function renderEmail(index){const draft=activeDrafts[index];document.getElementById('email-preview').innerHTML=`<div class="email-message"><div class="email-meta"><strong>To:</strong> ${esc(draft.to)}<br><strong>Subject:</strong> ${esc(draft.subject)}</div><pre>${esc(draft.body)}</pre></div>`;}
function download(text,name,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function safeCell(value){const text=String(value??'');return /^[=+@\t\r]|^-\D/.test(text)?"'"+text:text;}
function exportDay(){const rows=plan.jobs.map(j=>({job_id:j.id,service_date:j.serviceDate||'',client_group:clientRecord(data,j).stage,client_archived:isClientArchived(data,j)?'yes':'no',client_name:safeCell(j.name),address:safeCell(j.address),latitude:j.latitude??'',longitude:j.longitude??'',crew:getCrew(j.crew)?.name||'',status:j.status,requested_services:services(j).join('; '),completed_services:(j.completedServices||[]).join('; '),estimated_crew_minutes:j.minutes,reported_crew_minutes:j.status==='completed'?j.actualEnd-j.actualStart:'',reviewed_job_price_usd:j.price??'',modeled_cost_usd:plan.costs[j.id]?.cost??'',source:safeCell(j.source),travel_model:data.geographic?'OSRM car-road driving estimates; no live traffic':'Illustrative demo times'}));download(toCSV(rows),`groundskeeper-day-${ops.selectedDate()}.csv`,'text/csv;charset=utf-8');toast('Day report exported with the cost and source labels.');}
function currentImportRows(){return excelRows??normalizeLawnRows(parseCSV(document.getElementById('csv-input').value,{maxRows:100}));}
function invalidateImport(message=''){importPreview=null;document.getElementById('import-add').disabled=true;document.getElementById('import-results').innerHTML='';document.getElementById('import-error').textContent=message;}
function reviewImport(){try{const rows=currentImportRows();importPreview=importLawnRows(rows,data);const issues=[...excelWarnings,...importPreview.issues],blocked=importPreview.issues.filter(i=>i.severity==='error').length;document.getElementById('import-results').innerHTML=`<div class="import-summary"><strong>${importPreview.jobs.length} visit${importPreview.jobs.length===1?'':'s'} ready to add</strong> from ${rows.length} row${rows.length===1?'':'s'} · ${blocked} blocked</div>${importPreview.jobs.length?`<div class="table-scroll import-preview"><table><thead><tr><th>Customer & address</th><th>Services</th><th>Crew time</th><th>Job price</th></tr></thead><tbody>${importPreview.jobs.map(j=>`<tr><td><strong>${esc(j.name)}</strong><small>${esc(j.address)}</small></td><td>${serviceTags(j)}</td><td>${j.minutes??'Needs estimate'}${j.minutes===null?'':' min'}</td><td>${money(j.price)}</td></tr>`).join('')}</tbody></table></div>`:''}${issues.map(issue=>`<div class="import-issue ${issue.severity}"><strong>Row ${issue.row}</strong> · ${esc(issue.message)}</div>`).join('')}`;document.getElementById('import-add').disabled=!importPreview.jobs.length;document.getElementById('import-error').textContent=rows.length?'':'This worksheet has no customer rows.';}catch(error){invalidateImport(error.message);}}
function selectImportSheet(){invalidateImport();excelRows=null;excelWarnings=[];try{const result=lawnWorkbookRows(importWorkbook,document.getElementById('excel-sheet').value,globalThis.XLSX);excelRows=result.rows;excelWarnings=result.warnings;reviewImport();}catch(error){invalidateImport(error.message);}}
let manualLocation={version:0,session:0,request:null,selected:null,matches:[],addressKey:'',manual:false},destroyAddressPreview=()=>{},manualSaving=false;
const manualField=id=>document.getElementById('manual-'+id);
function clearManualLocation(){
 manualLocation.version++;Object.assign(manualLocation,{request:null,selected:null,matches:[],addressKey:'',manual:false});
 destroyAddressPreview();destroyAddressPreview=()=>{};manualField('location-preview').hidden=true;
 manualField('latitude').value='';manualField('longitude').value='';manualField('travel').value='';
 manualField('address-options').innerHTML='';manualField('location-later').checked=false;manualField('location-later-label').hidden=true;
 manualField('address-status').textContent='Coordinates will be filled automatically.';manualField('find-address').disabled=false;
 manualField('travel-help').textContent='Travel initially includes a road round trip from the crew base. The day plan updates the suggestion using the actual stop order.';
}
function showManualPreview(point){
 destroyAddressPreview();manualField('location-preview').hidden=false;
 destroyAddressPreview=mountAddressPreview(manualField('address-map'),point);
}
async function loadManualTravel(point,version){
 if(!hasCoordinates(data.depot))return;
 manualField('travel-help').textContent='Calculating road travel from the crew base…';
 try{
  const points=[data.depot,point,data.depot],raw=await fetchRoadData(roadRouteUrl(points));
  if(version!==manualLocation.version||!manualField('dialog').open)return;
  if(!Array.isArray(raw.waypoints)||raw.waypoints.some(p=>!Number.isFinite(p.distance)||p.distance>250))throw Error('Review the road access point.');
  const shape=parseRoadRoute(raw,{points,key:'manual',jobIds:['manual']}),minutes=shape.legs.reduce((sum,leg)=>sum+Math.ceil(leg.seconds/60),0);
  if(manualField('travel').value==='')manualField('travel').value=minutes;
  manualField('travel-help').textContent='Road return trip from base: '+minutes+' min. The day plan reallocates travel by stop order. You can edit this allowance.';
 }catch{if(version===manualLocation.version)manualField('travel-help').textContent='Road travel could not be calculated. Enter a travel allowance or review it in Price studio before relying on a price.';}
 if(version===manualLocation.version)updateManualQuote();
}
function selectManualAddress(index){
 const match=manualLocation.matches[index];if(!match||match.addressKey!==serviceAddressKey(manualField('address').value))return;
 manualLocation.selected=match;manualLocation.manual=false;
 manualField('latitude').value=match.latitude;manualField('longitude').value=match.longitude;
 manualField('location-later').checked=false;manualField('location-later-label').hidden=true;
 manualField('address-status').innerHTML='<strong>Address found · coordinates added</strong><span>'+esc(match.matchedAddress)+'</span><small>U.S. Census Geocoder · estimated street location</small>';
 showManualPreview(match);updateManualQuote();loadManualTravel(match,manualLocation.version);
}
async function lookupManualAddress(){
 const input=manualField('address').value,key=serviceAddressKey(input);
 if(addressLocationMatches(manualLocation.selected,input))return true;
 if(manualLocation.request&&manualLocation.addressKey===key)return manualLocation.request;
 let address;try{address=normalizeServiceAddress(input);}catch(error){manualField('address-status').textContent=error.message;return false;}
 const version=++manualLocation.version;manualLocation.addressKey=key;
 manualField('find-address').disabled=true;manualField('address-status').textContent='Finding the service address…';
 const request=(async()=>{
  try{
   if(location.protocol==='file:')throw Error('Address lookup needs the local app. Open Groundskeeper with its launcher.');
   const response=await business.authenticatedFetch('/api/lawn/geocode',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({address}),signal:AbortSignal.timeout(25000)});
   const payload=await response.json();if(!response.ok)throw Error(payload.error||'Address lookup is unavailable. Try again.');
   if(version!==manualLocation.version||!manualField('dialog').open||key!==serviceAddressKey(manualField('address').value))return false;
   manualLocation.matches=parseAddressLookup(payload,address);
   if(manualLocation.matches.length===1){selectManualAddress(0);return true;}
   manualField('location-later-label').hidden=false;
   if(!manualLocation.matches.length){manualField('address-status').textContent='No address match found. Check the street, city, state and ZIP, then try again. You can also save without a map location.';return false;}
   manualField('address-status').textContent='Several addresses match. Choose the correct service location.';
   manualField('address-options').innerHTML='<fieldset class="address-options"><legend>Matching service addresses</legend>'+manualLocation.matches.map((match,index)=>'<label><input type="radio" name="manual-address-match" value="'+index+'"><span>'+esc(match.matchedAddress)+'</span></label>').join('')+'</fieldset>';
   return false;
  }catch(error){
   if(version===manualLocation.version&&manualField('dialog').open){manualField('address-status').textContent=error.name==='TimeoutError'?'Address lookup timed out. Try again or save without a map location.':error.message;manualField('location-later-label').hidden=false;}
   return false;
  }finally{if(version===manualLocation.version){manualLocation.request=null;manualField('find-address').disabled=false;}}
 })();manualLocation.request=request;return request;
}
function manualQuote(){
 const explicit=manualField('minutes').value;
 const requested=Object.fromEntries(['mow','edge','mulch','hedge'].map(name=>[name,manualField(name).checked]));
 const selectedService=Object.values(requested).some(Boolean),estimate=explicit!==''?null:defaultServiceTime(requested,data.settings);
 const minutes=explicit!==''?Number(explicit):estimate.minutes;
 if(!selectedService)throw Error('Select the services for this visit.');
 if(minutes===null)throw Error(estimate.reason);
 if(manualField('travel').value==='')throw Error('Locate the address for road travel, or enter a travel allowance.');
 return {...quoteJob({minutes,travelMinutes:Number(manualField('travel').value),crew:getCrew(manualField('crew').value),materials:manualField('materials').value||'0.00',marginBps:data.settings.marginBps,minimum:data.settings.minimumPrice}),timeSource:explicit!==''?`Owner estimate · ${minutes} crew min`:estimate.source};
}
function updateManualQuote(){
 const card=manualField('price-suggestion');if(!card)return;
 try{const quote=manualQuote();card.innerHTML='<div><p class="eyebrow">SUGGESTED JOB PRICE</p><strong>'+money(quote.suggested)+'</strong><p>'+money(quote.cost)+' modeled cost · '+data.settings.marginBps/100+'% target margin · before tax</p></div><button type="button" class="button secondary" id="manual-use-suggestion">Use suggested price</button><small>'+esc(quote.timeSource)+'</small><small>Labor '+money(quote.labor)+' · travel '+money(quote.travel)+' · equipment '+money(quote.equipment)+' · materials '+money(quote.materials)+' · overhead '+money(quote.overhead)+'. Rates and default times come from Business settings. Review the price if the inputs change.</small>';}
 catch(error){card.innerHTML='<div><p class="eyebrow">SUGGESTED JOB PRICE</p><strong class="price-pending">A few details first</strong><p>'+esc(error.message)+'</p></div>';}
}
function openManual(){
 manualLocation.session++;manualSaving=false;manualField('form').reset();clearManualLocation();
 manualField('zone-wrapper').hidden=!!data.geographic;manualField('error').textContent='';
 manualField('crew').innerHTML=data.crews.map(c=>'<option value="'+esc(c.id)+'">'+esc(c.name)+'</option>').join('');
 document.querySelectorAll('#manual-form button[type="submit"]').forEach(button=>button.disabled=false);
 manualField('dialog').showModal();ops.prepareManual();updateManualQuote();
}
document.getElementById('manual-open').addEventListener('click',openManual);
manualField('find-address').addEventListener('click',()=>lookupManualAddress());
manualField('address').addEventListener('input',()=>{clearManualLocation();updateManualQuote();});
manualField('address').addEventListener('change',()=>{if(manualField('address').value.trim())lookupManualAddress();});
manualField('address-options').addEventListener('change',event=>{if(event.target.name==='manual-address-match')selectManualAddress(Number(event.target.value));});
manualField('dialog').addEventListener('close',()=>{manualLocation.version++;manualLocation.session++;destroyAddressPreview();destroyAddressPreview=()=>{};});
manualField('form').addEventListener('input',event=>{
 if(['manual-latitude','manual-longitude'].includes(event.target.id)){
  manualLocation.version++;manualLocation.selected=null;manualLocation.manual=true;manualLocation.request=null;manualField('find-address').disabled=false;
  manualField('address-status').textContent='Using coordinates entered by the operator. Review the map location.';
  try{const point=parseCoordinates(manualField('latitude').value,manualField('longitude').value);if(hasCoordinates(point)){showManualPreview(point);loadManualTravel(point,manualLocation.version);}}catch{}
 }
 if(event.target.id!=='manual-address')updateManualQuote();
});
manualField('form').addEventListener('change',event=>{if(event.target.id==='manual-crew')updateManualQuote();});
manualField('form').addEventListener('click',event=>{if(event.target.closest('#manual-use-suggestion')){try{manualField('price').value=manualQuote().suggested;}catch{}}});
manualField('form').addEventListener('submit',async event=>{
 event.preventDefault();if(manualSaving)return;
 const session=manualLocation.session,next=event.submitter?.value;manualSaving=true;manualField('error').textContent='';
 document.querySelectorAll('#manual-form button[type="submit"]').forEach(button=>button.disabled=true);
 try{
  if(data.jobs.length>=150)throw Error('This prototype supports 150 visits.');
  let coordinates=parseCoordinates(manualField('latitude').value,manualField('longitude').value);
  if(!manualField('location-later').checked&&!hasCoordinates(coordinates)){
   const found=await lookupManualAddress();if(session!==manualLocation.session)return;
   if(!found)throw Error('Review the address lookup above, choose a match, or select Save without a map location.');
   coordinates=parseCoordinates(manualField('latitude').value,manualField('longitude').value);
  }
  if(manualField('location-later').checked)coordinates={latitude:null,longitude:null};
  let number=data.jobs.length+1;while(data.jobs.some(j=>j.clientId==='MANUAL-'+number))number++;
  const row={client_id:'MANUAL-'+number,client_name:manualField('name').value,address:manualField('address').value,phone:manualField('phone').value,email:manualField('email').value,mow:manualField('mow').checked,edge:manualField('edge').checked,mulch:manualField('mulch').checked,hedge:manualField('hedge').checked,...coordinates,job_price_usd:manualField('price').value,estimated_minutes:manualField('minutes').value,crew_id:manualField('crew').value};
  const result=importLawnRows([row],data);if(!result.jobs.length)throw Error(result.issues.find(i=>i.severity==='error')?.message||'Check the job details.');
  const job=result.jobs[0],matched=addressLocationMatches(manualLocation.selected,row.address)?manualLocation.selected:null;
  const materials=manualField('materials').value||'0.00',travelText=manualField('travel').value,travelMinutes=travelText===''?0:Number(travelText);quoteJob({minutes:job.minutes||1,travelMinutes,crew:getCrew(job.crew),materials,marginBps:data.settings.marginBps,minimum:data.settings.minimumPrice});
  if(travelText!=='')job.quoteInputs={travelMinutes,marginBps:data.settings.marginBps,minimum:data.settings.minimumPrice};
  Object.assign(job,{source:'Owner manual entry',materials:Number(materials).toFixed(2),locationSource:matched?'U.S. Census Geocoder — estimated street address range':hasCoordinates(job)?'Operator-entered coordinates':null,locationLookup:matched?{provider:matched.provider,matchedAddress:matched.matchedAddress,precision:matched.precision,fetchedAt:matched.fetchedAt}:null,estimateSource:row.estimated_minutes?'Owner manual estimate':job.estimateSource,notes:manualField('notes').value.trim()});
  const zones={west:[240,160],central:[440,320],east:[820,200],lakeside:[740,440]},zone=manualField('zone').value;if(zones[zone]&&!data.geographic)[job.x,job.y]=zones[zone];
  ops.decorateManual(job);data.jobs.push(job);prepareGeoWorkspace(data);Object.assign(state,{optimized:false,dayPlanApplied:false,search:'',filter:'all',quoteJob:job.id});save();manualField('dialog').close();go(next==='pricing'?'pricing':'jobs');toast('Customer job added. Its suggested price and day plan are ready for review as road times load.');
 }catch(error){if(session===manualLocation.session)manualField('error').textContent=error.message;}
 finally{manualSaving=false;document.querySelectorAll('#manual-form button[type="submit"]').forEach(button=>button.disabled=false);}
});

function openBenchmark(){document.getElementById('job-content').innerHTML=`<form id="benchmark-form"><div class="dialog-top"><div><p class="eyebrow">PRICE COMPARISON</p><h2 id="job-title">Keep the context with the price.</h2></div><button type="button" class="icon-button" data-close aria-label="Close comparison form">${icon('close')}</button></div><p class="dialog-copy">Record a comparable quote or public price. This is an owner-entered reference, not an independently verified market rate.</p><label class="field-label" for="benchmark-label">Comparison label</label><input id="benchmark-label" type="text" maxlength="100" required><label class="field-label" for="benchmark-price">Quoted price ($)</label><input id="benchmark-price" type="number" min="0" max="1000000" step="0.01" required><label class="field-label" for="benchmark-source">Source, date, services and property context</label><textarea id="benchmark-source" rows="4" maxlength="600" required></textarea><p id="benchmark-error" class="form-error" role="alert"></p><div class="dialog-actions"><button type="button" class="button secondary" data-close>Cancel</button><button class="button primary" type="submit">Save comparison</button></div></form>`;document.getElementById('job-dialog').showModal();}

document.addEventListener('click',event=>{
 const target=event.target.closest('button,a,[data-pin]');if(!target)return;
 if(target.hasAttribute('data-close')){target.closest('dialog')?.close();return;}
 if(target.dataset.job){openJob(target.dataset.job);return;}
 if(target.dataset.pin){state.selected=target.dataset.pin;render();document.querySelector(`[data-pin="${state.selected}"]`)?.focus({preventScroll:true});return;}
 if(target.dataset.price){document.querySelectorAll('dialog[open]').forEach(d=>d.close());state.quoteJob=target.dataset.price;go('pricing');return;}
 if(target.dataset.crew){state.crew=target.dataset.crew;go('crew');return;}
 if(target.dataset.crewSelect){state.crew=target.dataset.crewSelect;render();save();return;}
 if(target.dataset.start){start(target.dataset.start);return;}
 if(target.dataset.finish){openFinish(target.dataset.finish);return;}
 if(target.dataset.zoom){state.zoom=target.dataset.zoom==='reset'?1:Math.max(1,Math.min(2.5,state.zoom+(target.dataset.zoom==='in'?.4:-.4)));render();return;}
 if(target.dataset.mapCrew){state.mapCrew=target.dataset.mapCrew;state.showRoadRoutes=true;state.focusRoute=true;go('today');return;}
 const action=target.dataset.action;
 if(action==='build-day-plan')openDayPlan();
 if(action==='undo-day-plan')undoDayPlan();
 if(action==='optimize'){state.optimized=true;render();save();document.querySelector('[data-action="optimize"]')?.focus({preventScroll:true});toast(`Route search complete. ${plan.unassigned.length?plan.unassigned.length+' visits need review.':baseline.travelMinutes-plan.travelMinutes+' fewer modeled travel minutes.'}`);}
 if(action==='baseline'){state.optimized=false;render();save();toast('Showing the saved-order baseline.');}
 if(action==='connections'){state.showRoadRoutes=state.showRoadRoutes===false;render();save();}
 if(action==='refresh-roads')ensureRoadRouting(true);
 if(action==='export')exportDay();
 if(action==='emails')openEmails();
 if(action==='add-benchmark')openBenchmark();
 if(action==='undo-restore'&&state.restoreBackup){data=state.restoreBackup;delete state.restoreBackup;document.getElementById('settings-dialog').close();save();render();toast('Your workspace before the demo restore is back.');}
});
