document.getElementById('excel-sheet').addEventListener('change',selectImportSheet);
document.getElementById('csv-file').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;invalidateImport();importWorkbook=null;excelRows=null;excelWarnings=[];document.getElementById('excel-sheet-controls').hidden=true;document.getElementById('csv-input').value='';document.getElementById('import-file-name').textContent=file.name;try{if(file.size>5_000_000)throw Error('Choose an Excel or CSV file under 5 MB.');if(/\.(xlsx|xls)$/i.test(file.name)){if(!globalThis.XLSX)throw Error('Excel reader could not load. Reopen the dashboard.');importWorkbook=globalThis.XLSX.read(await file.arrayBuffer(),{type:'array',sheetRows:102,cellFormula:true,cellHTML:false,bookVBA:false});if(!importWorkbook.SheetNames.length)throw Error('This workbook has no worksheets.');document.getElementById('excel-sheet').innerHTML=importWorkbook.SheetNames.map(name=>`<option value="${esc(name)}">${esc(name)}</option>`).join('');document.getElementById('excel-sheet-controls').hidden=false;document.getElementById('csv-paste-details').open=false;selectImportSheet();}else if(/\.csv$/i.test(file.name)){document.getElementById('csv-input').value=await file.text();document.getElementById('csv-paste-details').open=true;reviewImport();}else throw Error('Choose an .xlsx, .xls or .csv file.');}catch(error){invalidateImport('Could not read this file. '+error.message);}finally{event.target.value='';}});
document.getElementById('import-add').addEventListener('click',()=>{if(!importPreview?.jobs.length)return;try{const fresh=importLawnRows(currentImportRows(),data);if(data.jobs.length+fresh.jobs.length>150)throw Error('This prototype supports 150 visits. Choose a smaller import.');if(!fresh.jobs.length){reviewImport();return;}ops.registerImport(fresh.jobs);data.jobs.push(...fresh.jobs);prepareGeoWorkspace(data);state.optimized=false;state.search='';state.filter='all';document.getElementById('import-dialog').close();save();go('jobs');toast(`${fresh.jobs.length} visits added. Review prices and demo map pins as needed.`);invalidateImport();}catch(error){document.getElementById('import-error').textContent=error.message;}});
