try{
 const embedded=document.getElementById('lawn-demo-data');
 if(!embedded)throw Error('The dashboard assets are incomplete. Please rebuild the application.');
 seed=JSON.parse(embedded.textContent);
 await business.start({seed,onWorkspace:async saved=>{
  data=normalizeOperations(structuredClone(saved.data));state={...structuredClone(defaultBusinessState),...saved.state};
  landscape.initialize(data);state.viewDate??=data.date;
  if(!data.crews.some(crew=>crew.id===state.crew))state.crew=data.crews[0].id;
  render();
 }});
}catch(error){content.innerHTML='<div class="notice amber">The dashboard could not load. Reload the page to retry.</div>';document.getElementById('manual-open').disabled=true;}
